mapper.select:
SELECT *
FROM public.nocode_linkage_trigger
WHERE application_id = #{app}
AND application_version = #{version}
AND deleted = 0
ORDER BY target_object_id, target_field_id

SELECT *
FROM public.nocode_linkage_trigger
WHERE application_id = #{app}
AND application_version = #{version}
AND source_object_id = #{source}
AND deleted = 0
ORDER BY target_object_id, target_field_id

SELECT EXISTS (
    SELECT 1
    FROM public.nocode_linkage_trigger
    WHERE deleted = 0

        AND source_object_id = #{object}

)

    OR EXISTS (
        SELECT 1
        FROM public.nocode_linkage_trigger
        WHERE deleted = 0
        AND target_object_id = #{object}
    )

mapper.delete:
DELETE FROM public.nocode_linkage_trigger
WHERE application_id = #{app}
AND application_version = #{version}
